package routing

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

// Request is the routing input. All fields are optional except at least
// one of {Profile, ModelRef, Model, Harness, Provider} should be set
// (otherwise the engine has nothing to disambiguate on).
//
// Provider is present from day one (fixes ddx-8610020e — no soft-preference
// dropping).
type Request struct {
	Profile            string // "cheap" | "standard" | "smart"
	ModelRef           string // catalog alias (e.g. "qwen/qwen3.6")
	Model              string // exact concrete model pin
	Provider           string // exact provider pin; constrains routing to one provider identity
	Harness            string // hard preference; constrains routing to one harness
	Reasoning          string // public reasoning scalar
	Permissions        string // "safe" | "supervised" | "unrestricted"
	ProviderPreference string // "local-first" | "subscription-first" | "local-only" | "subscription-only"

	// EstimatedPromptTokens, when > 0, drives context-window gating.
	EstimatedPromptTokens int

	// RequiresTools, when true, requires the candidate to support tool calling.
	RequiresTools bool
	MinPower      int
	MaxPower      int
}

const (
	ProviderPreferenceLocalFirst        = "local-first"
	ProviderPreferenceSubscriptionFirst = "subscription-first"
	ProviderPreferenceLocalOnly         = "local-only"
	ProviderPreferenceSubscriptionOnly  = "subscription-only"
)

// MinContextWindow returns the minimum context window the request requires,
// derived from EstimatedPromptTokens with a safety margin.
func (r Request) MinContextWindow() int {
	if r.EstimatedPromptTokens <= 0 {
		return 0
	}
	// 1.25x safety margin for response tokens + tool overhead.
	return r.EstimatedPromptTokens + r.EstimatedPromptTokens/4
}

const (
	QuotaTrendUnknown    = "unknown"
	QuotaTrendHealthy    = "healthy"
	QuotaTrendBurning    = "burning"
	QuotaTrendExhausting = "exhausting"
)

// HarnessEntry is the harness-side input the caller (service) supplies.
// It is the routing engine's view of a registered harness; the engine does
// not import the harnesses package directly to keep the dependency narrow.
type HarnessEntry struct {
	Name                string
	Surface             string
	CostClass           string
	IsLocal             bool
	IsSubscription      bool
	IsHTTPProvider      bool
	AutoRoutingEligible bool
	TestOnly            bool
	ExactPinSupport     bool
	DefaultModel        string
	SupportedModels     []string
	SupportedReasoning  []string
	MaxReasoningTokens  int
	SupportedPerms      []string
	SupportsTools       bool

	// Available reflects the harness's discovered availability.
	Available bool

	// QuotaOK / QuotaPercentUsed reflect live quota state (when applicable).
	// SubscriptionOK gates subscription harnesses at the eligibility level:
	// when false, the candidate is ineligible regardless of score.
	QuotaOK          bool
	QuotaPercentUsed int
	QuotaStale       bool
	QuotaTrend       string // unknown|healthy|burning|exhausting
	QuotaReason      string
	SubscriptionOK   bool // false = hard gate; true = score-based demotion

	// InCooldown marks the entire harness as being in a failure cooldown.
	// When true the harness is demoted in score (via candidateInternal.InCooldown)
	// but not hard-rejected, so it can still win when all other harnesses are
	// also unavailable.
	InCooldown bool

	// Providers is the list of providers this harness can dispatch to.
	// For subprocess harnesses (claude/codex) this is typically a single
	// vendor entry. For the native "agent" harness it is the configured
	// list of HTTP providers.
	Providers []ProviderEntry
}

// ProviderEntry describes one provider available under a harness.
type ProviderEntry struct {
	Name               string
	BaseURL            string
	EndpointName       string
	EndpointBaseURL    string
	DefaultModel       string
	CostClass          string
	DiscoveredIDs      []string // models discovered via /v1/models or equivalent
	DiscoveryAttempted bool
	ContextWindows     map[string]int
	SupportsTools      bool

	// CostUSDPer1kTokens is the estimated blended USD cost per 1,000 tokens.
	// A zero value with CostSourceUnknown means the provider cost is unknown.
	CostUSDPer1kTokens float64
	// CostSource describes where CostUSDPer1kTokens came from: catalog,
	// subscription, user-config, or unknown.
	CostSource string

	// InCooldown reflects whether this provider is in a failure-cooldown window.
	InCooldown bool
}

const (
	// CostSourceCatalog means cost came from the model catalog.
	CostSourceCatalog = "catalog"
	// CostSourceSubscription means cost came from subscription quota pricing.
	CostSourceSubscription = "subscription"
	// CostSourceUnknown means no reliable cost estimate is available.
	CostSourceUnknown = "unknown"
	// CostSourceUserConfig means cost came from explicit user configuration.
	CostSourceUserConfig = "user-config"
)

// Decision is the routing engine's output: the picked candidate plus the
// full ranked list (including rejected ones with rejection reasons).
type Decision struct {
	Harness    string
	Provider   string
	Endpoint   string
	Model      string
	Reason     string
	Candidates []Candidate
}

// Candidate is one ranked routing option.
type Candidate struct {
	Harness            string
	Provider           string
	Endpoint           string
	Model              string
	Score              float64
	CostUSDPer1kTokens float64
	CostSource         string
	Power              int
	Eligible           bool
	Reason             string

	// FilterReason is the typed disqualification category, set at the
	// rejection site that decided why this candidate is ineligible.
	// Empty for eligible candidates. Service-layer code maps this to the
	// public FilterReason* string constants without parsing free-form
	// Reason text.
	FilterReason FilterReason

	// LatencyMS, SuccessRate, and CostClass expose the score-component
	// inputs so callers can render per-axis explanations alongside the
	// final Score. Zero / negative values mean unknown (see Inputs docs).
	LatencyMS   float64
	SuccessRate float64
	CostClass   string
	SpeedTPS    float64

	QuotaOK          bool
	QuotaPercentUsed int
	QuotaTrend       string
}

// FilterReason categorizes why a routing candidate was disqualified.
// The zero value (empty string) means the candidate is eligible.
type FilterReason string

const (
	// FilterReasonEligible is the zero value for an eligible candidate.
	FilterReasonEligible FilterReason = ""
	// FilterReasonContextTooSmall: candidate's context window is below the
	// request's MinContextWindow().
	FilterReasonContextTooSmall FilterReason = "context_too_small"
	// FilterReasonNoToolSupport: request needs tool calling but candidate
	// does not support it.
	FilterReasonNoToolSupport FilterReason = "no_tool_support"
	// FilterReasonReasoningUnsupported: candidate cannot satisfy the
	// requested reasoning policy.
	FilterReasonReasoningUnsupported FilterReason = "reasoning_unsupported"
	// FilterReasonUnhealthy: harness/provider is unavailable, in cooldown,
	// out of quota, or excluded by a hard provider-preference gate.
	FilterReasonUnhealthy FilterReason = "unhealthy"
	// FilterReasonScoredBelowTop: catch-all for ineligibility that does
	// not fit a more specific category (also used for capability
	// mismatches such as permissions/model-pin/exact-pin and for model
	// resolution failures).
	FilterReasonScoredBelowTop FilterReason = "scored_below_top"
	// FilterReasonPinMismatch: candidate was rejected because it does not
	// satisfy an explicit caller pin such as Provider.
	FilterReasonPinMismatch FilterReason = "pin_mismatch"
	// FilterReasonPowerMissing: automatic routing requires catalog power
	// metadata, but the candidate model is unknown or has zero power.
	FilterReasonPowerMissing FilterReason = "power_missing"
	// FilterReasonBelowMinPower: candidate model power is below req.MinPower.
	FilterReasonBelowMinPower FilterReason = "below_min_power"
	// FilterReasonAboveMaxPower: candidate model power is above req.MaxPower.
	FilterReasonAboveMaxPower FilterReason = "above_max_power"
	// FilterReasonExactPinOnly: catalog marks the model as only eligible for
	// explicit model pins.
	FilterReasonExactPinOnly FilterReason = "exact_pin_only"
	// FilterReasonNotAutoRoutable: catalog metadata exists but marks the
	// model inactive, deprecated, stale, or otherwise excluded from
	// automatic routing.
	FilterReasonNotAutoRoutable FilterReason = "not_auto_routable"
	// FilterReasonQuotaExhausted: provider is in the quota_exhausted state
	// with retry_after in the future. The candidate would have been eligible
	// otherwise.
	FilterReasonQuotaExhausted FilterReason = "quota_exhausted"
)

// NoViableCandidateError reports that routing evaluated candidates but every
// one failed a gate.
type NoViableCandidateError struct {
	Rejected int
	Model    string
	Provider string
	Harness  string
	MinPower int
	MaxPower int
}

func (e *NoViableCandidateError) Error() string {
	var pins []string
	if e.Model != "" {
		pins = append(pins, "model="+e.Model)
	}
	if e.Provider != "" {
		pins = append(pins, "provider="+e.Provider)
	}
	if e.Harness != "" {
		pins = append(pins, "harness="+e.Harness)
	}
	if e.MinPower > 0 {
		pins = append(pins, fmt.Sprintf("min_power=%d", e.MinPower))
	}
	if e.MaxPower > 0 {
		pins = append(pins, fmt.Sprintf("max_power=%d", e.MaxPower))
	}
	if len(pins) > 0 {
		return fmt.Sprintf("no viable routing candidate for pins %s: %d candidates rejected", strings.Join(pins, " "), e.Rejected)

package routing

import "testing"

func TestResolveUsesEndpointLoadToRankEquivalentLocalEndpoints(t *testing.T) {
	in := Inputs{
		Harnesses: []HarnessEntry{
			{
				Name:                "agent",
				CostClass:           "local",
				AutoRoutingEligible: true,
				Available:           true,
				ExactPinSupport:     true,
				SupportsTools:       true,
				Providers: []ProviderEntry{
					{Name: "local@desk-a", EndpointName: "desk-a", DefaultModel: "model-a", CostClass: "local"},
					{Name: "local@desk-b", EndpointName: "desk-b", DefaultModel: "model-a", CostClass: "local"},
				},
			},
		},
		ModelEligibility: func(model string) (ModelEligibility, bool) {
			if model != "model-a" {
				return ModelEligibility{}, false
			}
			return ModelEligibility{Power: 7, AutoRoutable: true}, true
		},
		EndpointLoadResolver: func(provider, endpoint, model string) (EndpointLoad, bool) {
			if provider != "local" || model != "model-a" {
				return EndpointLoad{}, false
			}
			switch endpoint {
			case "desk-a":
				return EndpointLoad{LeaseCount: 2, NormalizedLoad: 2.5}, true
			case "desk-b":
				return EndpointLoad{LeaseCount: 0, NormalizedLoad: 0.5}, true
			default:
				return EndpointLoad{}, false
			}
		},
	}

	dec, err := Resolve(Request{Harness: "agent", Model: "model-a"}, in)
	if err != nil {
		t.Fatalf("Resolve: %v", err)
	}
	if dec.Provider != "local@desk-b" || dec.Endpoint != "desk-b" {
		t.Fatalf("decision=%#v, want desk-b as least-loaded equivalent local endpoint", dec)
	}
	if len(dec.Candidates) < 2 {
		t.Fatalf("candidates=%#v, want both endpoints", dec.Candidates)
	}
	if dec.Candidates[0].Provider != "local@desk-b" {
		t.Fatalf("top candidate=%#v, want desk-b", dec.Candidates[0])
	}
}

package routehealth

import (
	"sort"
	"strings"
	"sync"

	"github.com/DocumentDrivenDX/fizeau/internal/provider/utilization"
)

// UtilizationKey identifies one provider endpoint/model utilization sample.
type UtilizationKey struct {
	Provider string
	Endpoint string
	Model    string
}

// EndpointLoad is the normalized load signal used by routing.
type EndpointLoad struct {
	LeaseCount           int
	NormalizedLoad       float64
	UtilizationFresh     bool
	UtilizationSaturated bool
}

// UtilizationStore retains the most recent utilization sample for each
// provider endpoint. It is safe for concurrent use.
type UtilizationStore struct {
	mu      sync.RWMutex
	samples map[UtilizationKey]utilization.EndpointUtilization
}

// NewUtilizationStore returns an empty utilization store.
func NewUtilizationStore() *UtilizationStore {
	return &UtilizationStore{
		samples: make(map[UtilizationKey]utilization.EndpointUtilization),
	}
}

// NormalizeUtilizationKey trims whitespace from the utilization dimensions.
func NormalizeUtilizationKey(provider, endpoint, model string) UtilizationKey {
	return UtilizationKey{
		Provider: strings.TrimSpace(provider),
		Endpoint: strings.TrimSpace(endpoint),
		Model:    strings.TrimSpace(model),
	}
}

// Record stores the latest utilization sample for key.
func (s *UtilizationStore) Record(provider, endpoint, model string, sample utilization.EndpointUtilization) {
	if s == nil {
		return
	}
	key := NormalizeUtilizationKey(provider, endpoint, model)
	if key.Provider == "" && key.Endpoint == "" && key.Model == "" {
		return
	}
	if sample.Freshness == "" {
		sample.Freshness = utilization.FreshnessFresh
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.samples == nil {
		s.samples = make(map[UtilizationKey]utilization.EndpointUtilization)
	}
	s.samples[key] = cloneUtilization(sample)
}

// EndpointLoads returns the normalized load per endpoint for provider/model.
// Fresh utilization samples are combined with the supplied lease counts;
// stale or missing samples fall back to lease counts only.
func (s *UtilizationStore) EndpointLoads(provider, model string, leaseCounts map[string]int) map[string]EndpointLoad {
	if s == nil {
		return nil
	}
	keyProvider := strings.TrimSpace(provider)
	keyModel := strings.TrimSpace(model)

	s.mu.RLock()
	defer s.mu.RUnlock()
	if len(s.samples) == 0 && len(leaseCounts) == 0 {
		return nil
	}

	keys := make(map[string]struct{})
	for endpoint := range leaseCounts {
		keys[endpoint] = struct{}{}
	}
	for key := range s.samples {
		if keyProvider != "" && key.Provider != keyProvider {
			continue
		}
		if keyModel != "" && key.Model != keyModel {
			continue
		}
		if key.Endpoint != "" {
			keys[key.Endpoint] = struct{}{}
		}
	}
	if len(keys) == 0 {
		return nil
	}

	out := make(map[string]EndpointLoad, len(keys))
	for endpoint := range keys {
		leaseCount := leaseCounts[endpoint]
		load := EndpointLoad{
			LeaseCount:       leaseCount,
			NormalizedLoad:   float64(leaseCount),
			UtilizationFresh: false,
		}
		key := NormalizeUtilizationKey(keyProvider, endpoint, keyModel)
		sample, ok := s.samples[key]
		if !ok && keyProvider != "" {
			// Allow provider-wide samples to match when the caller does not
			// have a fully-qualified endpoint name.
			sample, ok = s.samples[NormalizeUtilizationKey(keyProvider, "", keyModel)]
		}
		if !ok || sample.Freshness != utilization.FreshnessFresh {
			out[endpoint] = load
			continue
		}
		normalized, saturated := normalizedLoadFromSample(sample)
		load.NormalizedLoad = float64(leaseCount) + normalized
		load.UtilizationFresh = true
		load.UtilizationSaturated = saturated
		out[endpoint] = load
	}

	return out
}

func normalizedLoadFromSample(sample utilization.EndpointUtilization) (float64, bool) {
	var active int
	var queued int
	if sample.ActiveRequests != nil {
		active = *sample.ActiveRequests
	}
	if sample.QueuedRequests != nil {
		queued = *sample.QueuedRequests
	}
	if sample.MaxConcurrency != nil && *sample.MaxConcurrency > 0 {
		total := active + queued
		pressure := float64(total) / float64(*sample.MaxConcurrency)
		if pressure < 0 {
			pressure = 0
		}
		return pressure, total >= *sample.MaxConcurrency
	}
	if sample.CacheUsage != nil {
		pressure := *sample.CacheUsage
		if pressure < 0 {
			pressure = 0
		}
		return pressure, pressure >= 1
	}
	total := active + queued
	if total < 0 {
		total = 0
	}
	return float64(total), false
}

func cloneUtilization(sample utilization.EndpointUtilization) utilization.EndpointUtilization {
	out := sample
	if sample.ActiveRequests != nil {
		out.ActiveRequests = utilization.Int(*sample.ActiveRequests)
	}
	if sample.QueuedRequests != nil {
		out.QueuedRequests = utilization.Int(*sample.QueuedRequests)
	}
	if sample.CacheUsage != nil {
		out.CacheUsage = utilization.Float64(*sample.CacheUsage)
	}
	if sample.MaxConcurrency != nil {
		out.MaxConcurrency = utilization.Int(*sample.MaxConcurrency)
	}
	return out
}

// EndpointLoadList returns a deterministic endpoint ordering for tests.
func EndpointLoadList(loads map[string]EndpointLoad) []string {
	if len(loads) == 0 {
		return nil
	}
	out := make([]string, 0, len(loads))
	for endpoint := range loads {
		out = append(out, endpoint)
	}
	sort.Strings(out)
	return out
}

package fizeau

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	"github.com/DocumentDrivenDX/fizeau/internal/modelcatalog"
	"github.com/DocumentDrivenDX/fizeau/internal/routing"
)

var loadRoutingCatalog = modelcatalog.Default

// ResolveRoute resolves an under-specified RouteRequest to a concrete
// (Harness, Provider, Model) decision per CONTRACT-003.
//
// The implementation delegates to internal/routing.Resolve — the single
// routing engine that consolidates DDx-side harness-tier ranking and
// agent-side provider failover ordering.
func (s *service) ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error) {
	if err := ValidatePowerBounds(req.MinPower, req.MaxPower); err != nil {
		return nil, err
	}
	if err := ValidateRole(req.Role); err != nil {
		return nil, err
	}
	if err := ValidateCorrelationID(req.CorrelationID); err != nil {
		return nil, err
	}
	s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
	cat := serviceRoutingCatalog()
	profile := req.Profile
	if profile == "" {
		profile = reqProfileFromModelRef(cat, req.ModelRef)
	}
	modelRef := reqModelRefStripProfile(cat, req.ModelRef)
	providerPreference, err := providerPreferenceForProfile(cat, profile)
	if err != nil {
		return &RouteDecision{}, err
	}
	in := s.buildRoutingInputsWithCatalog(ctx, cat)

	rReq := routing.Request{
		Profile:               profile,
		ModelRef:              modelRef,
		Model:                 req.Model,
		Provider:              req.Provider,
		Harness:               req.Harness,
		Reasoning:             effectiveReasoningString(req.Reasoning),
		Permissions:           req.Permissions,
		ProviderPreference:    providerPreference,
		EstimatedPromptTokens: req.EstimatedPromptTokens,
		RequiresTools:         req.RequiresTools,
		MinPower:              req.MinPower,
		MaxPower:              req.MaxPower,
	}
	s.applyRouteAttemptCooldowns(&in)
	dec, err := routing.Resolve(rReq, in)
	if err != nil {
		if escalated, edec, eerr := escalateProfileLadder(rReq, in, err); escalated {
			dec = edec
			err = eerr
		}
	}
	result := routeDecisionFromInternal(dec)
	if err != nil {
		if result == nil {
			result = &RouteDecision{}
		}
		return result, publicRoutingError(err, result.Candidates)
	}
	s.applyStickyRouteLease(req.CorrelationID, result)
	// Cache the decision so RouteStatus can surface LastDecision.
	if result != nil {
		result.Model = resolveSubprocessModelAlias(result.Harness, result.Model)
		result.Power = catalogPowerForModel(cat, result.Model)
	}
	s.cacheRouteDecision(req.Model, result)
	return result, nil
}

func routeDecisionFromInternal(dec *routing.Decision) *RouteDecision {
	if dec == nil {
		return nil
	}
	return &RouteDecision{
		Harness:    dec.Harness,
		Provider:   dec.Provider,
		Endpoint:   dec.Endpoint,
		Model:      dec.Model,
		Reason:     dec.Reason,
		Candidates: routeCandidatesFromInternal(dec.Candidates),
	}
}

func routeCandidatesFromInternal(candidates []routing.Candidate) []RouteCandidate {
	if len(candidates) == 0 {
		return nil
	}
	out := make([]RouteCandidate, len(candidates))
	for i, candidate := range candidates {
		out[i] = routeCandidateFromInternal(candidate)
	}
	return out
}

func routeCandidateFromInternal(candidate routing.Candidate) RouteCandidate {
	return RouteCandidate{
		Harness:            candidate.Harness,
		Provider:           candidate.Provider,
		Endpoint:           candidate.Endpoint,
		Model:              candidate.Model,
		Score:              candidate.Score,
		CostUSDPer1kTokens: candidate.CostUSDPer1kTokens,
		CostSource:         candidate.CostSource,
		Eligible:           candidate.Eligible,
		Reason:             candidate.Reason,
		FilterReason:       publicFilterReason(candidate),
		Components: RouteCandidateComponents{
			Power:            candidate.Power,
			Cost:             candidate.CostUSDPer1kTokens,
			CostClass:        candidate.CostClass,
			LatencyMS:        candidate.LatencyMS,
			SpeedTPS:         candidate.SpeedTPS,
			SuccessRate:      candidate.SuccessRate,
			QuotaOK:          candidate.QuotaOK,
			QuotaPercentUsed: candidate.QuotaPercentUsed,
			QuotaTrend:       candidate.QuotaTrend,
			Capability:       capabilityScoreForCostClass(candidate.CostClass),
		},
	}
}

// publicFilterReason maps the typed FilterReason emitted by the internal
// routing engine to the public FilterReason* string constant. The internal
// constants are defined to share string values with the public surface, so
// this is a one-line passthrough — there is no string parsing.
func publicFilterReason(c routing.Candidate) string {
	if c.Eligible {
		return ""
	}
	return string(c.FilterReason)
}

// capabilityScoreForCostClass maps the harness cost class to a coarse
// numeric capability proxy. Mirrors the engine's costClassRank ordering
// (more expensive ≈ more capable) for reporting purposes only.
func capabilityScoreForCostClass(class string) float64 {
	switch class {
	case "local":
		return 0
	case "cheap":
		return 1
	case "medium", "":
		return 2
	case "expensive":
		return 3
	case "experimental":
		return -1
	default:
		return 0
	}
}

// escalateProfileLadder walks routing.ProfileEscalationLadder when Resolve
// returns a "no eligible candidate" error and the request's profile is in
// the ladder. Returns (true, decision, nil) when a higher tier resolves to
// an eligible candidate, or (true, nil, *routing.ErrNoLiveProvider) when
// the entire remaining ladder is also empty. Returns (false, _, _) when
// escalation does not apply (hard pin error, profile not in ladder, etc.).
func escalateProfileLadder(req routing.Request, in routing.Inputs, origErr error) (bool, *routing.Decision, error) {
	if origErr == nil || req.Profile == "" {
		return false, nil, nil
	}
	if !shouldEscalateOnError(origErr) {
		return false, nil, nil
	}
	startIdx := -1
	for i, p := range routing.ProfileEscalationLadder {
		if p == req.Profile {
			startIdx = i
			break
		}
	}
	if startIdx < 0 {
		return false, nil, nil
	}
	for i := startIdx + 1; i < len(routing.ProfileEscalationLadder); i++ {
		probe := req
		probe.Profile = routing.ProfileEscalationLadder[i]
		dec, err := routing.Resolve(probe, in)
		if err == nil && dec != nil && dec.Harness != "" {
			return true, dec, nil
		}
	}
	return true, nil, &routing.ErrNoLiveProvider{
		PromptTokens:  req.EstimatedPromptTokens,
		RequiresTools: req.RequiresTools,
		StartingTier:  req.Profile,
	}
}

// shouldEscalateOnError gates ladder escalation to "no eligible candidate"
// errors. Hard caller-pin conflicts (ErrHarnessModelIncompatible,
// ErrProfilePinConflict) are surfaced as-is — escalating past an explicit
// pin would silently change the caller's intent.
func shouldEscalateOnError(err error) bool {
	var modelErr *routing.ErrHarnessModelIncompatible
	if errors.As(err, &modelErr) {
		return false
	}
	var pinErr *routing.ErrProfilePinConflict
	if errors.As(err, &pinErr) {
		return false
	}
	return true
}

func publicRoutingError(err error, candidates []RouteCandidate) error {
	var modelErr *routing.ErrHarnessModelIncompatible
	if errors.As(err, &modelErr) {
		return withRouteCandidates(&ErrHarnessModelIncompatible{
			Harness:         modelErr.Harness,
			Model:           modelErr.Model,
			SupportedModels: append([]string(nil), modelErr.SupportedModels...),
		}, candidates)
	}
	var profileErr *routing.ErrProfilePinConflict
	if errors.As(err, &profileErr) {
		return withRouteCandidates(&ErrProfilePinConflict{
			Profile:           profileErr.Profile,
			ConflictingPin:    profileErr.ConflictingPin,
			ProfileConstraint: profileErr.ProfileConstraint,
		}, candidates)
	}
	var noProfileErr *routing.ErrNoProfileCandidate
	if errors.As(err, &noProfileErr) {
		return withRouteCandidates(&ErrNoProfileCandidate{
			Profile:           noProfileErr.Profile,
			MissingCapability: noProfileErr.MissingCapability,
			Rejected:          noProfileErr.Rejected,
		}, candidates)
	}
	var noLiveErr *routing.ErrNoLiveProvider
	if errors.As(err, &noLiveErr) {
		return withRouteCandidates(&ErrNoLiveProvider{
			PromptTokens:  noLiveErr.PromptTokens,
			RequiresTools: noLiveErr.RequiresTools,
			StartingTier:  noLiveErr.StartingTier,
