func (s *service) liveProviderEntries(ctx context.Context, providerName string, pcfg ServiceProviderEntry, cat *modelcatalog.Catalog) []routing.ProviderEntry {
	if providerUsesLiveDiscovery(pcfg.Type) && s.catalog != nil {
		endpoints := modelDiscoveryEndpoints(pcfg)
		out := make([]routing.ProviderEntry, 0, len(endpoints))
		for _, endpoint := range endpoints {
			ids, ok := s.probeEndpointDiscoveredIDs(ctx, pcfg, endpoint.BaseURL)
			if !ok || len(ids) == 0 {
				continue
			}
			routeName := providerName
			if len(endpoints) > 1 {
				routeName = endpointProviderRef(providerName, endpoint.Name)
			}
			entry := routing.ProviderEntry{
				Name:               routeName,
				BaseURL:            endpoint.BaseURL,
				EndpointName:       endpoint.Name,
				EndpointBaseURL:    endpoint.BaseURL,
				DefaultModel:       pcfg.Model,
				CostClass:          providerRoutingCostClass(pcfg.Type),
				DiscoveredIDs:      ids,
				DiscoveryAttempted: true,
				ContextWindows:     buildProviderContextWindows(cat, pcfg.Model, ids),
				SupportsTools:      providerSupportsTools(cat, pcfg.Model, ids),
			}
			s.applyEndpointRoutingCost(&entry, pcfg, cat)
			out = append(out, entry)
		}
		return out
	}
	entry := routing.ProviderEntry{
		Name:           providerName,
		BaseURL:        pcfg.BaseURL,
		DefaultModel:   pcfg.Model,
		CostClass:      providerRoutingCostClass(pcfg.Type),
		ContextWindows: buildProviderContextWindows(cat, pcfg.Model, nil),
		SupportsTools:  providerSupportsTools(cat, pcfg.Model, nil),
	}
	s.applyEndpointRoutingCost(&entry, pcfg, cat)
	return []routing.ProviderEntry{entry}
}

// buildProviderContextWindows assembles the ContextWindows map for a
// ProviderEntry from the model catalog. Entries are added for the provider's
// configured DefaultModel and every DiscoveredID that has a non-zero
// context_window declared in the catalog. Models the catalog does not know
// about are omitted (engine treats missing entries as unknown context).
func buildProviderContextWindows(cat *modelcatalog.Catalog, defaultModel string, discoveredIDs []string) map[string]int {
	if cat == nil {
		return nil
	}
	out := make(map[string]int)
	if defaultModel != "" {
		if n := cat.ContextWindowForModel(defaultModel); n > 0 {
			out[defaultModel] = n
		}
	}
	for _, id := range discoveredIDs {
		if id == "" {
			continue
		}
		if _, exists := out[id]; exists {
			continue
		}
		if n := cat.ContextWindowForModel(id); n > 0 {
			out[id] = n
		}
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

// providerSupportsTools returns whether the provider should be advertised as
// supporting tools to the routing engine. Defaults to true; only flips to
// false when the catalog explicitly marks every relevant model (the
// DefaultModel and any DiscoveredIDs) with no_tools=true.
func providerSupportsTools(cat *modelcatalog.Catalog, defaultModel string, discoveredIDs []string) bool {
	if cat == nil {
		return true
	}
	checked := false
	if defaultModel != "" {
		if cat.SupportsToolsForModel(defaultModel) {
			return true
		}
		checked = true
	}
	for _, id := range discoveredIDs {
		if id == "" {
			continue
		}
		if cat.SupportsToolsForModel(id) {
			return true
		}
		checked = true
	}
	if !checked {
		return true
	}
	return false
}

func anyProviderSupportsTools(providers []routing.ProviderEntry) bool {
	for _, p := range providers {
		if p.SupportsTools {
			return true
		}
	}
	return false
}

func providerUsesLiveDiscovery(providerType string) bool {
	switch normalizeServiceProviderType(providerType) {
	case "openai", "openrouter", "lmstudio", "llama-server", "omlx", "rapid-mlx", "ollama", "lucebox", "vllm", "minimax", "qwen", "zai":
		return true
	default:
		return false
	}
}

func (s *service) applyEndpointRoutingCost(entry *routing.ProviderEntry, pcfg ServiceProviderEntry, cat *modelcatalog.Catalog) {
	if entry == nil {
		return
	}
	if providerTypeIsLocalEndpoint(pcfg.Type) {
		if s.opts.LocalCostUSDPer1kTokens > 0 {
			entry.CostUSDPer1kTokens = s.opts.LocalCostUSDPer1kTokens
			entry.CostSource = routing.CostSourceUserConfig
		} else {
			entry.CostUSDPer1kTokens = 0
			entry.CostSource = routing.CostSourceUnknown
		}
		return
	}
	if cost, ok := catalogCostUSDPer1kTokens(cat, entry.DefaultModel); ok {
		entry.CostUSDPer1kTokens = cost
		entry.CostSource = routing.CostSourceCatalog
		return
	}
	entry.CostUSDPer1kTokens = 0
	entry.CostSource = routing.CostSourceUnknown
}

func (s *service) applySubscriptionRoutingCost(entry *routing.HarnessEntry, cat *modelcatalog.Catalog) {
	if entry == nil || !entry.IsSubscription {
		return
	}
	baseCost, ok := catalogCostUSDPer1kTokens(cat, entry.DefaultModel)
	if !ok {
		baseCost, ok = catalogCostUSDPer1kTokens(cat, subscriptionFallbackProfile(entry.Name))
		if !ok {
			baseCost = 0
		}
	}
	cost := subscriptionEffectiveCostUSDPer1kTokens(baseCost, entry.QuotaPercentUsed, s.subscriptionCostCurve())
	entry.Providers = []routing.ProviderEntry{{
		CostUSDPer1kTokens: cost,
		CostSource:         routing.CostSourceSubscription,
	}}
}

func providerTypeIsLocalEndpoint(providerType string) bool {
	switch normalizeServiceProviderType(providerType) {
	case "lmstudio", "llama-server", "omlx", "rapid-mlx", "ollama", "lucebox", "vllm":
		return true
	default:
		return false
	}
}

func providerRoutingCostClass(providerType string) string {
	if providerTypeIsLocalEndpoint(providerType) {
		return "local"
	}
	return "medium"
}

func subscriptionFallbackProfile(harnessName string) string {
	switch harnessName {
	case "claude", "codex", "gemini":
		return "standard"
	default:
		return ""
	}
}

func catalogCostUSDPer1kTokens(cat *modelcatalog.Catalog, modelID string) (float64, bool) {
	if cat == nil || strings.TrimSpace(modelID) == "" {
		return 0, false
	}
	entry, ok := cat.LookupModel(modelID)
	if !ok {
		resolved := resolveCatalogCostModel(cat, modelID)
		if resolved == "" {
			return 0, false
		}
		entry, ok = cat.LookupModel(resolved)
		if !ok {
			return 0, false
		}
	}
	input := entry.CostInputPerM
	if input == 0 {
		input = entry.CostInputPerMTok
	}
	output := entry.CostOutputPerM
	if output == 0 {
		output = entry.CostOutputPerMTok
	}
	switch {
	case input > 0 && output > 0:
		return ((input + output) / 2) / 1000, true
	case input > 0:
		return input / 1000, true
	case output > 0:
		return output / 1000, true
	default:
		return 0, false
	}
}

func resolveCatalogCostModel(cat *modelcatalog.Catalog, ref string) string {
	for _, surface := range []modelcatalog.Surface{
		modelcatalog.SurfaceAgentOpenAI,
		modelcatalog.SurfaceAgentAnthropic,
		modelcatalog.SurfaceCodex,
		modelcatalog.SurfaceClaudeCode,

		}}
	}

	histRate, hasHist := in.HistoricalSuccess[h.Name]
	if !hasHist {
		histRate = -1
	}

	// Enumerate providers. For harnesses with no providers (subprocess harnesses
	// with vendor-managed billing), emit a single virtual provider entry.
	providers := h.Providers
	if len(providers) == 0 {
		providers = []ProviderEntry{{Name: ""}}
	}

	out := make([]rankedCandidate, 0, len(providers))
	for _, p := range providers {
		model, reason := resolveModel(h, p, req, in)
		ctxWin := 0
		if p.ContextWindows != nil {
			ctxWin = p.ContextWindows[model]
		}
		entryCaps := caps
		entryCaps.ContextWindow = ctxWin
		entryCaps.SupportsTools = caps.SupportsTools || p.SupportsTools
		if len(p.DiscoveredIDs) > 0 {
			entryCaps.SupportedModels = nil
		}

		key := ProviderModelKey(p.Name, p.EndpointName, model)
		obs := in.ObservedSpeedTPS[key]
		if obs == 0 && p.EndpointName != "" {
			obs = in.ObservedSpeedTPS[ProviderModelKey(p.Name, "", model)]
		}
		providerSuccessRate := -1.0
		if rate, ok := in.ProviderSuccessRate[key]; ok {
			providerSuccessRate = rate
		} else if p.EndpointName != "" {
			if rate, ok := in.ProviderSuccessRate[ProviderModelKey(p.Name, "", model)]; ok {
				providerSuccessRate = rate
			}
		}
		latencyMS := in.ObservedLatencyMS[key]
		if latencyMS == 0 && p.EndpointName != "" {
			latencyMS = in.ObservedLatencyMS[ProviderModelKey(p.Name, "", model)]
		}
		power := candidatePower(in.ModelEligibility, model)
		endpointLoad := EndpointLoad{}
		if in.EndpointLoadResolver != nil {
			loadProvider, loadEndpoint := candidateLoadIdentity(h, p)
			if resolved, ok := in.EndpointLoadResolver(loadProvider, loadEndpoint, model); ok {
				endpointLoad = resolved
			}
		} else if load, ok := in.EndpointLoads[key]; ok {
			endpointLoad = load
		}

		gateReq := resolveRequestReasoning(req, h.Surface, in.ReasoningResolver)

		eligible := true
		var filterReason FilterReason
		if reason == "" {
			// Subscription quota is a hard availability gate and must be
			// reported before catalog metadata gates. An exhausted Claude/Codex/
			// Gemini account is never a viable candidate, regardless of whether
			// the resolved model has complete power metadata.
			if h.IsSubscription && !h.SubscriptionOK {
				eligible = false
				reason = h.QuotaReason
				if reason == "" {
					if h.QuotaStale {
						reason = "subscription quota unavailable"
					} else {
						reason = "subscription quota exhausted"
					}
				}
				filterReason = FilterReasonUnhealthy
			} else if g, fr := CheckPowerEligibility(in.ModelEligibility, model, gateReq); g != "" {
				eligible = false
				reason = g
				filterReason = fr
			} else if g, fr := CheckGating(entryCaps, gateReq); g != "" {
				eligible = false
				reason = g
				filterReason = fr
			}
		} else {
			eligible = false
			// resolveModel rejection — model resolution is a capability
			// mismatch with no specific public category, so fall through
			// to the catch-all.
			filterReason = FilterReasonScoredBelowTop
		}

		// Hard preference filtering.
		if eligible {
			switch req.ProviderPreference {
			case ProviderPreferenceLocalOnly:
				if !h.IsLocal {
					eligible = false
					reason = "preference is local-only"
					filterReason = FilterReasonUnhealthy
				}
			case ProviderPreferenceSubscriptionOnly:
				if !h.IsSubscription {
					eligible = false
					reason = "preference is subscription-only"
					filterReason = FilterReasonUnhealthy
				}
			}
		}

		if eligible && req.Provider != "" && req.Provider != candidateProviderIdentity(h, p) {
			// Hard provider pin: reject every other provider identity, even
			// when a non-pinned candidate would otherwise score higher.
			eligible = false
			reason = fmt.Sprintf("provider override requires %s", req.Provider)
			filterReason = FilterReasonPinMismatch
		}

		inCooldown := false
		if p.Name != "" && p.InCooldown {
			inCooldown = true
		} else if p.Name != "" && in.CooldownDuration > 0 {
			if failedAt, ok := in.ProviderCooldowns[p.Name]; ok {
				if in.Now.Sub(failedAt) < in.CooldownDuration {
					inCooldown = true
				}
			}
		}

		// Provider quota-exhausted gate. The state machine lives in the
		// service layer; the engine consumes the projected map of
		// provider-name → retry_after. Apply only when the candidate would
		// otherwise have been eligible — disqualifying an already-rejected
		// candidate with a different reason would lose the original signal.
		var quotaExhaustedRetryAfter time.Time
		if eligible {
			providerKey := candidateProviderIdentity(h, p)
			if providerKey != "" && len(in.ProviderQuotaExhaustedUntil) > 0 {
				if retryAfter, ok := in.ProviderQuotaExhaustedUntil[providerKey]; ok && retryAfter.After(in.Now) {
					eligible = false
					reason = fmt.Sprintf("provider %s quota exhausted until %s", providerKey, retryAfter.Format(time.RFC3339))
					filterReason = FilterReasonQuotaExhausted
					quotaExhaustedRetryAfter = retryAfter
				}
			}
		}

		ci := candidateInternal{
			Harness:               h.Name,
			Provider:              p.Name,
			EndpointName:          p.EndpointName,
			Model:                 model,
			CostClass:             candidateCostClass(h, p),
			CostUSDPer1kTokens:    p.CostUSDPer1kTokens,
			CostSource:            normalizeCostSource(p.CostSource),
			Power:                 power,
			IsSubscription:        h.IsSubscription,
			QuotaOK:               h.QuotaOK,
			QuotaPercentUsed:      h.QuotaPercentUsed,
			QuotaStale:            h.QuotaStale,
			QuotaTrend:            h.QuotaTrend,
			SubscriptionOK:        h.SubscriptionOK,
			HistoricalSuccessRate: histRate,
			ProviderSuccessRate:   providerSuccessRate,
			ObservedTokensPerSec:  obs,
			ObservedLatencyMS:     latencyMS,
			InCooldown:            inCooldown || h.InCooldown,
			ProviderAffinityMatch: req.Provider != "" && req.Provider == candidateProviderIdentity(h, p),
			ProviderPreference:    req.ProviderPreference,
			EndpointLoad:          endpointLoad.NormalizedLoad,
			EndpointLoadFresh:     endpointLoad.UtilizationFresh,
			EndpointSaturated:     endpointLoad.UtilizationSaturated,
		}
		out = append(out, rankedCandidate{
			out: Candidate{
				Harness:            h.Name,
				Provider:           p.Name,
				Endpoint:           p.EndpointName,
				Model:              model,
				CostUSDPer1kTokens: p.CostUSDPer1kTokens,
				CostSource:         normalizeCostSource(p.CostSource),
				Power:              power,
				Eligible:           eligible,
				Reason:             reason,
				FilterReason:       filterReason,
				LatencyMS:          latencyMS,
				SuccessRate:        providerSuccessRate,
				CostClass:          candidateCostClass(h, p),
				SpeedTPS:           obs,
				QuotaOK:            h.QuotaOK,
				QuotaPercentUsed:   h.QuotaPercentUsed,
				QuotaTrend:         h.QuotaTrend,
			},
			internal:                 ci,
			quotaExhaustedRetryAfter: quotaExhaustedRetryAfter,
		})
	}
	return out
}

func candidatePower(lookup func(string) (ModelEligibility, bool), model string) int {
	if lookup == nil || model == "" {
		return 0
	}
	eligibility, ok := lookup(model)
	if !ok {
		return 0
	}
	return eligibility.Power
}

